public class AutowiredAnnotationBeanPostProcessor 
        extends InstantiationAwareBeanPostProcessorAdapter {

    private final Map<Class<?>, InjectionMetadata> injectionMetadataCache =
            new ConcurrentHashMap<>(256);

    private final Set<Class<? extends Annotation>> autowiredAnnotationTypes =
            new LinkedHashSet<>(4);

    public AutowiredAnnotationBeanPostProcessor() {
        autowiredAnnotationTypes.add(Autowired.class);
        autowiredAnnotationTypes.add(Value.class);
    }

    @Override
    public PropertyValues postProcessPropertyValues(
            PropertyValues pvs, PropertyDescriptor[] pds, 
            Object bean, String beanName) {
        InjectionMetadata metadata = findAutowiringMetadata(beanName, bean.getClass());
        metadata.inject(bean, beanName, pvs);
        return pvs;
    }
}

public class InjectionMetadata {

    private final Class<?> targetClass;
    private final Collection<InjectedElement> checkedElements;

    public InjectionMetadata(Class<?> targetClass, Collection<InjectedElement> elements) {
        this.targetClass = targetClass;
        this.checkedElements = elements;
    }

    public void inject(Object target, String beanName, PropertyValues pvs) throws Throwable {
        ReflectionUtils.doWithLocalFields(targetClass, field -> {
            InjectedElement element = findInjectedElement(targetClass, field);
            if (element != null) {
                element.inject(target, beanName, pvs);
            }
        });
        ReflectionUtils.doWithLocalMethods(targetClass, method -> {
            method = BridgeMethodResolver.findBridgedMethod(method);
            InjectedElement element = findInjectedElement(targetClass, method);
            if (element != null) {
                element.inject(target, beanName, pvs);
            }
        });
    }
}

public class DefaultSingletonBeanRegistry extends SimpleAliasRegistry {

    private final Map<String, Object> singletonObjects = new ConcurrentHashMap<>(256);
    private final Map<String, Object> earlySingletonObjects = new ConcurrentHashMap<>(16);
    private final Map<String, ObjectFactory<?>> singletonFactories = new HashMap<>(16);
    private final Set<String> singletonsCurrentlyInCreation =
            Collections.newSetFromMap(new ConcurrentHashMap<>(16));
    private final Set<String> registeredSingletons = new LinkedHashSet<>(256);
}

protected Object getSingleton(String beanName, boolean allowEarlyReference) {
    Object singletonObject = this.singletonObjects.get(beanName);
    if (singletonObject == null && isSingletonCurrentlyInCreation(beanName)) {
        synchronized (this.singletonObjects) {
            singletonObject = this.earlySingletonObjects.get(beanName);
            if (singletonObject == null && allowEarlyReference) {
                ObjectFactory<?> singletonFactory = this.singletonFactories.get(beanName);
                if (singletonFactory != null) {
                    singletonObject = singletonFactory.getObject();
                    this.earlySingletonObjects.put(beanName, singletonObject);
                    this.singletonFactories.remove(beanName);
                }
            }
        }
    }
    return singletonObject;
}

protected <T> T doGetBean(String name, Class<T> requiredType, 
                         Object[] args, boolean typeCheckOnly) {
    String beanName = transformedBeanName(name);
    Object bean;

    Object sharedInstance = getSingleton(beanName);
    if (sharedInstance != null) {
        bean = getObjectForBeanInstance(sharedInstance, name, beanName, null);
    } else {
        if (isPrototypeCurrentlyInCreation(beanName)) {
            throw new BeanCurrentlyInCreationException(beanName);
        }

        BeanFactory parentBeanFactory = getParentBeanFactory();
        if (parentBeanFactory != null) {
            bean = parentBeanFactory.getBean(name, requiredType);
        }

        if (!typeCheckOnly) {
            markBeanAsCreated(beanName);
        }

        try {
            RootBeanDefinition mbd = getMergedLocalDefinition(beanName);
            String[] dependsOn = mbd.getDependsOn();
            if (dependsOn != null) {
                for (String dep : dependsOn) {
                    getBean(dep);
                    registerDependentBean(dep, beanName);
                }
            }
            if (mbd.isSingleton()) {
                sharedInstance = getSingleton(beanName, () -> createBean(beanName, mbd, args));
                bean = getObjectForBeanInstance(sharedInstance, name, beanName, mbd);
            }
        } catch (BeansException ex) {
            beanCreationException.principalHasBeenApplied(beanName, mbd);
            throw ex;
        }
    }
    return (T) bean;
}

protected Object createBean(String beanName, RootBeanDefinition mbd, 
                            Object[] args) throws BeanCreationException {
    RootBeanDefinition mbdToUse = mbd;
    Class<?> resolvedClass = resolveBeanClass(mbd, beanName);

    try {
        Object bean = resolveBeforeInstantiation(beanName, mbdToUse);
        if (bean != null) {
            return bean;
        }
    } catch (Throwable ex) {
        throw new BeanCreationException(beanName, 
            "BeanPostProcessor before instantiation failed", ex);
    }

    Object beanInstance = doCreateBean(beanName, mbdToUse, args);
    return beanInstance;
}

protected Object doCreateBean(String beanName, RootBeanDefinition mbd,
                              Object[] args) throws BeanCreationException {
    BeanWrapper instanceWrapper = createBeanInstance(beanName, mbd, args);
    Object bean = instanceWrapper.getWrappedInstance();

    boolean earlySingletonExposure = mbd.isSingleton() && 
                                       this.allowCircularReferences &&
                                       isSingletonCurrentlyInCreation(beanName);
    if (earlySingletonExposure) {
        addSingletonFactory(beanName, () -> getEarlyBeanReference(beanName, mbd, bean));
    }

    populateBean(beanName, mbd, instanceWrapper);
    bean = initializeBean(beanName, bean, mbd);

    return bean;
}

